import java.util.concurrent.locks.ReentrantLock;

public class ThreadSafeMovingAverage {
    private final int windowSize;
    private final ReentrantLock lock = new ReentrantLock();
    private final AtomicReference<double[]> values = new AtomicReference<>();

    public ThreadSafeMovingAverage(int windowSize) {
        this.windowSize = windowSize;
        this.values.set(new double[windowSize]);
    }

    public void add(double value) {
        lock.lock();
        try {
            double[] arr = values.get();

            if (arr.length < windowSize) {
                System.arraycopy(arr, 0, arr, 1, arr.length - 1);
                arr[0] = value;
            } else {
                for (int i = 1; i < arr.length; i++) {
                    arr[i - 1] = arr[i];
                }
                arr[arr.length - 1] = value;
            }

            while (!values.compareAndSet(arr, values.get())) {}
        } finally {
            lock.unlock();
        }
    }

    public double average() {
        lock.lock();
        try {
            if (values.get().length == 0) {
                return 0.0;
            }
            double sum = 0.0;
            for (double d : values.get()) {
                sum += d;
            }
            return sum / values.get().length;
        } finally {
            lock.unlock();
        }
    }
}
